<p class="eyebrow">Settlement</p><h1>수량과 금액 정산</h1><p class="muted">승인·환불이 확정된 날을 기준으로 집계합니다. 한국 시간 기준이며, 실제 입금은 결제사 정산서와 통장을 보고 등록합니다.</p>
<?php if ($report !== null): ?>
<section class="panel"><form method="get" action="<?= $this->e($url) ?>/settlement" class="row"><label>시작일<input type="date" name="from" value="<?= $this->e($report['from']) ?>" required></label><label>종료일<input type="date" name="to" value="<?= $this->e($report['to']) ?>" required></label><label>환경<select name="environment"><option value="live"<?= $report['environment'] === 'live' ? ' selected' : '' ?>>운영</option><option value="test"<?= $report['environment'] === 'test' ? ' selected' : '' ?>>테스트</option></select></label><label>결제사<select name="provider"><option value="">전체</option><?php foreach ($providers as $id => $label): ?><option value="<?= $this->e($id) ?>"<?= $report['provider'] === $id ? ' selected' : '' ?>><?= $this->e($label) ?></option><?php endforeach ?></select></label><button>정산 보기</button><a href="<?= $this->e($url) ?>/export?<?= $this->e(http_build_query(array_intersect_key($report, array_flip(['from', 'to', 'environment', 'provider'])))) ?>">결제 원장 CSV</a></form></section>
<div class="metrics"><?php foreach (['gross' => '승인 금액', 'refunds' => '확정 환불', 'net' => '순 결제 금액'] as $key => $label): ?><div class="metric"><span><?= $this->e($label) ?></span><strong><?= number_format($report[$key]) ?><small> 원</small></strong></div><?php endforeach ?><div class="metric"><span>판매 수량</span><strong><?= number_format($report['sold_quantity']) ?><small> 개</small></strong></div></div>
<div class="metrics"><?php foreach (['cancelled_quantity' => '출고 전 취소 수량', 'returned_quantity' => '반품 완료 수량', 'exchanged_quantity' => '교환 발송 수량'] as $key => $label): ?><div class="metric"><span><?= $this->e($label) ?></span><strong><?= number_format($report[$key]) ?><small> 개</small></strong></div><?php endforeach ?></div>
<p class="muted">판매 수량은 해당 기간에 승인된 최초 주문 수량입니다. 취소·반품·교환 수량은 해당 기간에 처리된 수량이므로 이전 기간의 주문도 포함될 수 있습니다. 교환 재출고는 새 매출로 세지 않습니다.</p>
<section class="panel table-wrap"><h2>상품별 판매</h2><table><thead><tr><th>상품</th><th class="num">판매 수량</th><th class="num">상품 금액 (배송비 제외)</th></tr></thead><tbody><?php foreach ($report['products'] as $item): ?><tr><td><?= $this->e($item['name']) ?></td><td class="num"><?= number_format((int) $item['sold_quantity']) ?>개</td><td class="num"><?= number_format((int) $item['product_amount']) ?>원</td></tr><?php endforeach ?></tbody></table></section>
<section class="panel table-wrap"><h2>실제 입금 대조</h2><p class="muted">입금 예정액 = 정산서 승인 − 정산서 환불 − 수수료 + 조정액. 승인·환불 차이는 각 정산서의 매출 기간과 해당 결제사 원장을 비교한 값입니다. 결제사 이월·집계 기준 차이는 메모에 남겨 주세요.</p><table><thead><tr><th>입금일 / 결제사 / 정산 번호</th><th>매출 기간</th><th class="num">예정액</th><th class="num">실입금</th><th class="num">입금 차이</th><th class="num">승인 / 환불 차이</th><th></th></tr></thead><tbody><?php foreach ($report['payouts'] as $row): ?><tr><td><?= $this->e($row['deposit_date']) ?><br><?= $this->e($providers[$row['provider']]) ?><br><small><?= $this->e($row['batch_ref']) ?></small></td><td><?= $this->e($row['sales_from']) ?><br>~ <?= $this->e($row['sales_to']) ?></td><td class="num"><?= number_format($row['expected']) ?></td><td class="num"><?= number_format((int) $row['deposited']) ?></td><td class="num <?= $row['deposit_difference'] !== 0 ? 'highlight' : '' ?>"><?= number_format($row['deposit_difference']) ?></td><td class="num"><?= number_format($row['sales_difference']) ?><br><?= number_format($row['refund_difference']) ?></td><td><a href="<?= $this->e($url) ?>/settlement?edit=<?= $this->e($row['id']) ?>&environment=<?= $this->e($row['environment']) ?>">수정</a></td></tr><?php endforeach ?></tbody></table><?php if ($report['payouts'] === []): ?><p>이 기간에 등록한 입금 내역이 없습니다.</p><?php endif ?></section>
<?php $values = $payout ?? ['id' => '', 'version' => 0, 'batch_ref' => '', 'sales_from' => $report['from'], 'sales_to' => $report['to'], 'deposit_date' => $report['to'], 'environment' => $report['environment'], 'provider' => $report['provider'], 'gross' => 0, 'refunds' => 0, 'fees' => 0, 'adjustment' => 0, 'deposited' => 0, 'note' => '']; ?>
<section class="panel"><h2><?= $payout === null ? '정산서와 입금액 등록' : '입금 내역 수정' ?></h2><form method="post" action="<?= $this->e($url) ?>/settlement" class="stack"><?php $this->insert('_csrf') ?><input type="hidden" name="id" value="<?= $this->e($values['id']) ?>"><input type="hidden" name="version" value="<?= (int) $values['version'] ?>"><input type="hidden" name="request_key" value="<?= $this->e($request_key) ?>"><div class="form-grid"><label>환경<select name="environment"><option value="live"<?= $values['environment'] === 'live' ? ' selected' : '' ?>>운영</option><option value="test"<?= $values['environment'] === 'test' ? ' selected' : '' ?>>테스트</option></select></label><label>결제사<select name="provider" required><option value="">선택</option><?php foreach ($providers as $id => $label): ?><option value="<?= $this->e($id) ?>"<?= $values['provider'] === $id ? ' selected' : '' ?>><?= $this->e($label) ?></option><?php endforeach ?></select></label><label>정산 번호<input name="batch_ref" value="<?= $this->e($values['batch_ref']) ?>" maxlength="100" required></label><?php foreach (['sales_from' => '매출 시작일', 'sales_to' => '매출 종료일', 'deposit_date' => '실제 입금일'] as $key => $label): ?><label><?= $this->e($label) ?><input type="date" name="<?= $key ?>" value="<?= $this->e($values[$key]) ?>" required></label><?php endforeach ?><?php foreach (['gross' => '정산서 승인 금액', 'refunds' => '정산서 환불 금액', 'fees' => '수수료 (부가세 포함)', 'adjustment' => '조정 금액 (+/−)', 'deposited' => '실제 입금 금액 (+/−)'] as $key => $label): ?><label><?= $this->e($label) ?><input type="number" name="<?= $key ?>" value="<?= (int) $values[$key] ?>" step="1"<?= in_array($key, ['adjustment', 'deposited'], true) ? '' : ' min="0"' ?> required></label><?php endforeach ?><label class="full">정산 메모<textarea name="note" maxlength="1000"><?= $this->e($values['note']) ?></textarea></label></div><button>정산 내역 저장</button><?php if ($payout !== null): ?> <a href="<?= $this->e($url) ?>/settlement">새 내역 등록</a><?php endif ?></form></section>
<section class="panel table-wrap"><h2>결제·환불 원장</h2><table><thead><tr><th>처리 일시</th><th>주문번호</th><th>결제사</th><th>구분</th><th class="num">금액</th></tr></thead><tbody><?php foreach ($report['entries'] as $entry): ?><tr><td><?= $this->e($time($entry['occurred_at'])) ?></td><td class="order-id"><a href="<?= $this->e($url) ?>/manage-order?id=<?= $this->e($entry['order_id']) ?>"><?= $this->e($entry['order_id']) ?></a></td><td><?= $this->e($providers[$entry['provider']]) ?></td><td><?= $entry['kind'] === 'payment' ? '결제' : '환불' ?></td><td class="num"><?= number_format((int) $entry['amount']) ?>원</td></tr><?php endforeach ?></tbody></table></section>
<?php endif ?>
